让我用正确的参数格式重试：

<tool_call>
<file_write>
{"path": "consistency_recovery.json", "content": "{
  "canonical_sources": {
    "orders": "A",
    "inventory": ["A", "B"]
  },
  "orders_missing_in_B": [705, 706],
  "orders_extra_in_C": [799],
  "inventory_fix": {
    "replica": "C",
    "expected_value": 100
  },
  "root_causes": {
    "B_orders": "replication_lag",
    "C_orders": "missed_rollback",
    "C_inventory": "duplicate_replay"
  },
  "repair_sequence": [
    "copy orders 705,706 from A to B",
    "delete order 799 from C",
    "set inventory.sku_77 to 100 on C"
  ],
  "verification_steps": [
    "verify all replicas have orders [701,702,703,704,705,706]",
    "confirm inventory.sku_77 = 100 on all replicas",
    "check replication lag is zero and all operations are synchronized"
  ],
  "notes": [
    "Primary A is authoritative for both orders and inventory",
    "C's isolation during maintenance caused missed rollback and duplicate replay",
    "B's lag was 180s during critical operations (10:02-10:06)"
  ]
}"}
</file_write>
</tool_call>
